//! Casper protocol domain types + wire conversion.
//!
//! Mirrors `models/src/main/scala/coop/rchain/casper/protocol/CasperMessage.scala`. The scalapb
//! `*Proto` types (generated by prost from `proto/casper.proto`) are kept private; these hand-written
//! domain types are the public API and carry `from(&Proto)` / `to_proto(&self)`. Sorting for
//! deterministic serialization (Law 16) happens here, at the domain layer, using `BTreeSet`/`BTreeMap`
//! (see `BlockMessage::to_proto`).

use std::collections::BTreeMap;

use prost::Message as _;
use rchain_crypto::hash::blake2b256_hash::Blake2b256Hash;
use rchain_shared::refined::{BlockHeight, NonNegI64, SeqNum};
use rchain_shared::serialize::Serialize;

use crate::block::state_hash::StateHash;
use crate::block_hash::BlockHash;
use crate::casper::protocol::deploy_service::DeployInfo;
use crate::proto::casper::PCost as PCostProto;
use crate::proto::casper::*;
use crate::validator::Validator;
use rchain_shared::base16;

