/// A produce event (port of `ProduceEvent`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProduceEvent {
    pub channels_hash: Vec<u8>,
    pub hash: Vec<u8>,
    pub persistent: bool,
    pub times_repeated: i32,
}

/// A consume event (port of `ConsumeEvent`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ConsumeEvent {
    pub channels_hashes: Vec<Vec<u8>>,
    pub hash: Vec<u8>,
    pub persistent: bool,
}

/// A comm event (port of `CommEvent`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CommEvent {
    pub consume: ConsumeEvent,
    pub produces: Vec<ProduceEvent>,
    pub peeks: Vec<Peek>,
}

/// An execution-trace event (port of the sealed `Event`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Event {
    Produce(ProduceEvent),
    Consume(ConsumeEvent),
    Comm(CommEvent),
}

impl Event {
    pub fn from_proto(e: &EventProto) -> Result<Event, crate::errors::ModelsError> {
        match &e.event_instance {
            Some(event_proto::EventInstance::Produce(pe)) => Ok(Event::Produce(ProduceEvent {
                channels_hash: pe.channels_hash.clone(),
                hash: pe.hash.clone(),
                persistent: pe.persistent,
                times_repeated: pe.times_repeated,
            })),
            Some(event_proto::EventInstance::Consume(ce)) => Ok(Event::Consume(ConsumeEvent {
                channels_hashes: ce.channels_hashes.clone(),
                hash: ce.hash.clone(),
                persistent: ce.persistent,
            })),
            Some(event_proto::EventInstance::Comm(ce)) => {
                let consume = ce
                    .consume
                    .as_ref()
                    .ok_or(crate::errors::ModelsError::Malformed("malformed CommEvent: missing consume"))?;
                Ok(Event::Comm(CommEvent {
                    consume: ConsumeEvent {
                        channels_hashes: consume.channels_hashes.clone(),
                        hash: consume.hash.clone(),
                        persistent: consume.persistent,
                    },
                    produces: ce
                        .produces
                        .iter()
                        .map(|p| ProduceEvent {
                            channels_hash: p.channels_hash.clone(),
                            hash: p.hash.clone(),
                            persistent: p.persistent,
                            times_repeated: p.times_repeated,
                        })
                        .collect(),
                    peeks: ce
                        .peeks
                        .iter()
                        .map(|p| Peek {
                            channel_index: p.channel_index,
                        })
                        .collect(),
                }))
            }
            None => Err(crate::errors::ModelsError::Malformed("malformed Event: empty")),
        }
    }

    pub fn to_proto(&self) -> EventProto {
        match self {
            Event::Produce(pe) => EventProto {
                event_instance: Some(event_proto::EventInstance::Produce(ProduceEventProto {
                    channels_hash: pe.channels_hash.clone(),
                    hash: pe.hash.clone(),
                    persistent: pe.persistent,
                    times_repeated: pe.times_repeated,
                })),
            },
            Event::Consume(ce) => EventProto {
                event_instance: Some(event_proto::EventInstance::Consume(ConsumeEventProto {
                    channels_hashes: ce.channels_hashes.clone(),
                    hash: ce.hash.clone(),
                    persistent: ce.persistent,
                })),
            },
            Event::Comm(ce) => EventProto {
                event_instance: Some(event_proto::EventInstance::Comm(CommEventProto {
                    consume: Some(ConsumeEventProto {
                        channels_hashes: ce.consume.channels_hashes.clone(),
                        hash: ce.consume.hash.clone(),
                        persistent: ce.consume.persistent,
                    }),
                    produces: ce
                        .produces
                        .iter()
                        .map(|p| ProduceEventProto {
                            channels_hash: p.channels_hash.clone(),
                            hash: p.hash.clone(),
                            persistent: p.persistent,
                            times_repeated: p.times_repeated,
                        })
                        .collect(),
                    peeks: ce
                        .peeks
                        .iter()
                        .map(|p| PeekProto {
                            channel_index: p.channel_index,
                        })
                        .collect(),
                })),
            },
        }
    }
}

