/// System deploy data (port of the sealed `SystemDeployData`).
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum SystemDeployData {
    Slash(Validator),
    CloseBlock,
    Empty,
}

impl SystemDeployData {
    pub fn from_proto(p: &SystemDeployDataProto) -> Result<Self, crate::errors::ModelsError> {
        match &p.system_deploy {
            Some(system_deploy_data_proto::SystemDeploy::SlashSystemDeploy(sd)) => {
                Ok(SystemDeployData::Slash(Validator::try_from(
                    sd.slashed_validator.as_slice(),
                )?))
            }
            Some(system_deploy_data_proto::SystemDeploy::CloseBlockSystemDeploy(_)) => {
                Ok(SystemDeployData::CloseBlock)
            }
            None => Ok(SystemDeployData::Empty),
        }
    }

    pub fn to_proto(&self) -> SystemDeployDataProto {
        match self {
            SystemDeployData::Slash(validator) => SystemDeployDataProto {
                system_deploy: Some(system_deploy_data_proto::SystemDeploy::SlashSystemDeploy(
                    SlashSystemDeployDataProto {
                        slashed_validator: validator.as_bytes().to_vec(),
                    },
                )),
            },
            SystemDeployData::CloseBlock => SystemDeployDataProto {
                system_deploy: Some(
                    system_deploy_data_proto::SystemDeploy::CloseBlockSystemDeploy(
                        CloseBlockSystemDeployDataProto {},
                    ),
                ),
            },
            SystemDeployData::Empty => SystemDeployDataProto { system_deploy: None },
        }
    }
}

/// A processed system deploy (port of the sealed `ProcessedSystemDeploy`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ProcessedSystemDeploy {
    Succeeded {
        event_list: Vec<Event>,
        system_deploy: SystemDeployData,
    },
    Failed {
        event_list: Vec<Event>,
        error_msg: String,
    },
}

impl ProcessedSystemDeploy {
    pub fn from_proto(p: &ProcessedSystemDeployProto) -> Result<Self, crate::errors::ModelsError> {
        let deploy_log: Result<Vec<Event>, crate::errors::ModelsError> =
            p.deploy_log.iter().map(Event::from_proto).collect();
        let deploy_log = deploy_log?;
        if p.error_msg.is_empty() {
            let system_deploy = match p.system_deploy.as_ref() {
                Some(sd) => SystemDeployData::from_proto(sd)?,
                None => SystemDeployData::Empty,
            };
            Ok(ProcessedSystemDeploy::Succeeded {
                event_list: deploy_log,
                system_deploy,
            })
        } else {
            Ok(ProcessedSystemDeploy::Failed {
                event_list: deploy_log,
                error_msg: p.error_msg.clone(),
            })
        }
    }

    pub fn to_proto(&self) -> ProcessedSystemDeployProto {
        match self {
            ProcessedSystemDeploy::Succeeded {
                event_list,
                system_deploy,
            } => ProcessedSystemDeployProto {
                system_deploy: Some(system_deploy.to_proto()),
                deploy_log: event_list.iter().map(Event::to_proto).collect(),
                error_msg: String::new(),
            },
            ProcessedSystemDeploy::Failed {
                event_list,
                error_msg,
            } => ProcessedSystemDeployProto {
                system_deploy: None,
                deploy_log: event_list.iter().map(Event::to_proto).collect(),
                error_msg: error_msg.clone(),
            },
        }
    }
}

